import {fa,escapeHTML as esc,defaults,fields,lessons,validateValue,cleanSettings,validateSignup,passwordStrength,lessonStatus,stats,safeProject,csvCell,formatTime,english} from './lib/model.js';
import {Game,WORLD} from './lib/game.js';
import {configured,getClient,friendlyError,getAccountData,saveProject,recordProgress,redirectURL} from './lib/backend.js';
import {discoveryHome,discoveryIdea,discoveryResearch,bindDiscovery,initTheme} from './lib/discovery.js';
import {prototypePage,bindPrototype,getDemoUser,submitPrototypeIdea} from './lib/prototype.js';

initTheme();

const GUEST_KEY='hplgame-guest-v2',app=document.querySelector('#app');
let user=null,profile=null,projects=[],progress={},onboarding=false,route='',active=null;
let draft={...defaults},selected='jump',history=[],redo=[],dirty=false,revision=0,saveTimer,savePromise;
let saveMessage='',dataError='',online=navigator.onLine,loading=false,modalReturn,blockedDestination='';
let game,frame,lastFrame=0,sound=false,audioContext,pendingCompletion=null;
let authReturnHash='#/dashboard',pendingIntent=null,workshopView='game',authBusy=false;
let otpState={email:'',type:'',cooldown:0,timer:null};
const PROTECTED_ROUTE=/^(learn|dashboard|projects|help|admin|workshop(?:\/|$))/;
function isProtectedRoute(path){return PROTECTED_ROUTE.test(path);}
function currentDisplayName(){return profile?.full_name||profile?.display_name||user?.user_metadata?.full_name||'بازی‌ساز';}
function rememberAuthIntent(intent={}){pendingIntent={route:intent.route||authReturnHash||'#/dashboard',kind:intent.kind||'route',id:intent.id||null};authReturnHash=pendingIntent.route;}
function openAuthWall(intent={}){rememberAuthIntent(intent);navigate('login');}
function clearOtpState(){clearInterval(otpState.timer);otpState={email:'',type:'',cooldown:0,timer:null};}
function updateOtpUi(){const label=document.querySelector('#otp-countdown'),button=document.querySelector('[data-action="resend-otp"]');if(label)label.textContent=otpState.cooldown?`ارسال دوباره تا ${fa(otpState.cooldown)} ثانیه دیگر`:'می‌توانی کد را دوباره بفرستی.';if(button)button.disabled=otpState.cooldown>0;}
function startOtpCooldown(){clearInterval(otpState.timer);otpState.cooldown=60;updateOtpUi();otpState.timer=setInterval(()=>{otpState.cooldown=Math.max(0,otpState.cooldown-1);updateOtpUi();if(!otpState.cooldown)clearInterval(otpState.timer);},1000);}
async function resumeAuthIntent(){const intent=pendingIntent;pendingIntent=null;const target=(intent?.route||authReturnHash||'#/dashboard').replace(/^#\/?/,'')||'dashboard';if(intent?.kind==='lesson'&&intent.id)return startLesson(intent.id);if(intent?.kind==='project'&&intent.id)return openProject(intent.id);navigate(target);}
const input={left:false,right:false,jump:false};
const stateLabels={not_started:'شروع نشده',in_progress:'در حال انجام',completed:'کامل‌شده',locked:'قفل‌شده'};

function readGuest(){
  try{
    const raw=JSON.parse(localStorage.getItem(GUEST_KEY)||'{}');
    projects=Array.isArray(raw.projects)?raw.projects.slice(0,100).filter(p=>typeof p.id==='string').map(safeProject):[];
    progress=raw.progress&&typeof raw.progress==='object'?Object.fromEntries(lessons.filter(l=>l.published&&['in_progress','completed'].includes(raw.progress[l.id]?.status)).map(l=>[l.id,raw.progress[l.id]])):{};
    onboarding=raw.onboarding===true;
    if(!localStorage.getItem(GUEST_KEY)&&localStorage.getItem('hplgame-state-v1')){
      const legacy=JSON.parse(localStorage.getItem('hplgame-state-v1'));
      projects=[newProject(lessons[0],{speed:legacy.moveSteps,jump:legacy.jumpHeight,starScore:10})];
    }
  }catch{projects=[];progress={};onboarding=false;}
}
function writeGuest(){try{localStorage.setItem(GUEST_KEY,JSON.stringify({projects,progress,onboarding}));return true;}catch{return false;}}
function newProject(l,settings=l.defaults){return{id:crypto.randomUUID(),title:l.id==='first-star'?'سفر ستاره':'پرش دقیق',project_data:{lesson_id:l.id,settings:cleanSettings(settings,l.defaults)},updated_at:null};}
function currentLesson(){return lessons.find(l=>l.id===active?.project_data.lesson_id)||lessons[0];}
function nextLesson(){return lessons.find(l=>l.published&&!['locked','completed'].includes(lessonStatus(l,progress)))||lessons[0];}
function button(text,action,kind='secondary',extra=''){return `<button type="button" class="btn ${kind}" data-action="${action}" ${extra}>${text}</button>`;}
function link(text,to,kind='secondary'){return `<a class="btn ${kind}" href="#/${to}">${text}</a>`;}
function avatar(name='هوپی'){return `<span class="avatar" role="img" aria-label="${esc(name)}">${esc(Array.from(name)[0]||'آ')}</span>`;}
function shell(content){
  const s=stats(progress),name=user?currentDisplayName():(getDemoUser()?.name||'بازی‌ساز'),mobileActive=route.startsWith('workshop/')?'projects':route;
  const nav=[['','خانه','⌂'],['idea','ایده و مسیر من','✧'],['research','پژوهش هفتهٔ اول','◈'],['learn','مسیرهای آموزشی','⚑'],['dashboard','داشبورد من','◈'],['projects','بازی‌های من','▣'],['help','راهنما و هوپی','✦']];
  return `<a class="skip" href="#main-content">رفتن به محتوا</a><div class="app-shell"><aside class="sidebar"><a class="brand" href="#/"><span class="brand-mark" aria-hidden="true">✦</span><span><strong dir="ltr">HPLGAME</strong><small>بازی بساز، یاد بگیر</small></span></a><div class="profile-card">${avatar(name)}<div><b>${esc(name)}</b><small>${user?'حساب یادگیری':getDemoUser()?'کاربر واردشده · آزمایشی':'بازدیدکننده'}</small></div></div><nav class="side-nav" aria-label="ناوبری اصلی">${nav.map(([id,label,icon])=>`<a class="nav-item ${route===id?'active':''}" href="#/${id}" ${route===id?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${label}</a>`).join('')}${profile?.role==='admin'?'<a class="nav-item" href="#/admin">پنل مدیریت</a>':''}</nav><div class="sidebar-bottom"><p>پیشرفت: ${fa(s.completed)} از ${fa(lessons.filter(l=>l.published).length)} مرحله</p><progress value="${s.percent}" max="100" aria-label="درصد پیشرفت"></progress><p>${fa(s.xp)} XP آموزشی</p><a href="#/privacy">حریم خصوصی</a> · <a href="#/terms">قوانین</a></div></aside><div class="main-area"><header class="topbar"><span class="topbar-note">کارگاه ایده‌های کوچک، ماجراهای بزرگ</span><a href="#/" class="mobile-brand" dir="ltr">✦ HPLGAME</a><div class="top-actions"><button type="button" class="btn theme-toggle" id="theme-toggle" aria-pressed="${document.documentElement.dataset.theme==='dark'}">${document.documentElement.dataset.theme==='dark'?'☀ حالت روشن':'☾ حالت دارک'}</button>${user?`<details class="profile-menu"><summary>${avatar(name)} ${esc(name)}</summary><div><a href="#/dashboard">پروفایل و پیشرفت</a>${button('خروج از حساب','logout','ghost')}</div></details>`:`${getDemoUser()?`<span class="proto-header-user">${esc(getDemoUser().name)} · ${getDemoUser().premium?'پرو آزمایشی':'واردشده'}</span><button class="btn secondary" data-proto="logout">خروج</button>`:`<button class="btn secondary" data-proto-auth="login">ورود</button><button class="btn primary" data-proto-auth="signup">ثبت‌نام رایگان</button>`}`}</div></header>${!online?'<div class="notice" role="status">آفلاین هستی. برای همگام‌سازی دوباره به اینترنت وصل شو.</div>':''}<main id="main-content" class="page-wrap" tabindex="-1">${loading?'<p role="status">در حال دریافت حساب و پروژه‌ها…</p>':dataError?`<div class="notice error" role="alert">${esc(dataError)} ${button('تلاش دوباره','reload-account')}</div>`:content}</main><footer class="page-footer"><span>© HPLGAME · یادگیری با ساختن</span><a href="#/help">راهنما و هوپی</a><a href="#/privacy">حریم خصوصی</a><a href="#/admin">پنل مدیریت</a></footer></div></div><nav class="mobile-nav" aria-label="ناوبری موبایل">${[['','خانه','⌂'],['idea','مسیر من','⚑'],['research','بازخورد','◈'],[user?'dashboard':'login','حساب کاربری','●']].map(([id,label,icon])=>`<a class="mobile-nav-item ${mobileActive===id?'active':''}" href="#/${id}" ${mobileActive===id?'aria-current="page"':''}><span aria-hidden="true">${icon}</span><small>${label}</small></a>`).join('')}</nav><button class="hopi-launch btn secondary" data-action="coach">✦ راهنمایی هوپی</button><div id="modal-root"></div><div id="toast" role="status" aria-live="polite"></div>`;
}
function render(){
  stopAnimation();
  const viewRoute=isProtectedRoute(route)&&!user?'login':route;
  const content=viewRoute.startsWith('studio/')?prototypePage(viewRoute):viewRoute.startsWith('workshop/')?workshop():({'':home,idea:discoveryIdea,research:discoveryResearch,learn:learning,dashboard,projects:projectList,help,privacy,terms,admin})[viewRoute]?.()||authPage(viewRoute);
  const authModal=!user&&pendingIntent&&['login','signup','otp'].includes(viewRoute);
  app.innerHTML=shell(authModal?home():content);
  if(authModal){
    document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop auth-backdrop"><div class="modal auth-modal" role="dialog" aria-modal="true" aria-label="ورود یا ثبت‌نام"><button class="modal-close" data-action="cancel-auth" aria-label="بستن پنجره ورود">×</button>${content}</div></div>`;
    document.querySelector('.app-shell').inert=true;document.querySelector('.mobile-nav').inert=true;document.querySelector('.hopi-launch').inert=true;
    const root=document.querySelector('#modal-root');root.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();handleAction('cancel-auth');}if(e.key==='Tab'){const nodes=[...root.querySelectorAll('button:not(:disabled),input,select,a[href]')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};
  }
  bind();updateOtpUi();if(authModal)document.querySelector('#modal-root input')?.focus();
  if(route.startsWith('workshop/')&&!loading&&!dataError&&user){paintGame();if(game?.status==='running')animate();}
}
function home(){return discoveryHome();}

function lessonCards(){return `<div class="card-grid three">${lessons.map((l,i)=>{const status=lessonStatus(l,progress),pre=lessons.find(p=>p.id===l.prerequisite);return `<article class="feature-card ${status==='locked'?'locked-card':'pink-card'}"><span class="badge">دنیای ${fa(i+1)} · ${l.published?'رایگان':'نمونه توسعه'}</span><h3>${l.title}</h3><p>${l.description}</p><p>سطح: ${l.difficulty}</p><p>پیش‌نیاز: ${pre?.title||'ندارد'}</p><b>${stateLabels[status]}</b>${l.published?button(status==='completed'?'تکرار مرحله':i===0?'شروع مرحله ۱ 🚀':'شروع مرحله','lesson','primary',`data-lesson="${l.id}" ${status==='locked'?'disabled':''}`):'<small>در دست ساخت؛ هنوز قابل اجرا نیست.</small>'}</article>`;}).join('')}</div>`;}
function learning(){return `<div class="page-heading"><div><span class="eyebrow">نقشه یادگیری</span><h1>از اولین ستاره تا دنیای خودت</h1><p>قفل مرحله بعد با کامل کردن پیش‌نیاز باز می‌شود.</p></div>${button('ادامه یادگیری','start','primary')}</div>${lessonCards()}`;}
function dashboard(){const s=stats(progress),l=nextLesson(),name=currentDisplayName();return `<div class="page-heading"><div><h1>${esc(name)}، ادامه بده!</h1><p>مرحله فعلی: ${l.title}</p></div>${button('ادامه یادگیری','start','primary')}</div><div class="metric-grid"><div class="metric-card"><span>پیشرفت</span><b>${fa(s.percent)}٪</b><progress max="100" value="${s.percent}" aria-label="درصد پیشرفت"></progress></div><div class="metric-card"><span>امتیاز آموزشی</span><b>${fa(s.xp)} XP</b></div><div class="metric-card"><span>مراحل کامل‌شده</span><b>${fa(s.completed)}</b></div><div class="metric-card"><span>پروژه‌ها</span><b>${fa(projects.length)}</b></div></div>${user?`<section class="panel profile-edit"><h2>پروفایل</h2><p>نام کامل: <strong>${esc(currentDisplayName())}</strong></p><p>موبایل: <span dir="ltr">${esc(profile.phone||'ثبت نشده')}</span></p><p dir="ltr">${esc(profile.email)}</p><p>اطلاعات تماس خصوصی است.</p>${button('درخواست حذف حساب و داده‌ها','deletion-request','ghost')}</section>`:''}<div class="section-head"><h2>نقشه مراحل</h2></div>${lessonCards()}`;}
function projectList(){return `<div class="page-heading"><div><h1>بازی‌های من</h1><p>${user?'پروژه‌های خصوصی حساب تو':'پروژه‌های ذخیره‌شده فقط روی این دستگاه'}</p></div>${button('ساخت پروژه تازه','new-project','primary')}</div>${projects.length?`<div class="card-grid three">${projects.map(p=>`<article class="feature-card pink-card"><h2>${esc(p.title)}</h2><p>مرحله: ${lessons.find(l=>l.id===p.project_data.lesson_id)?.title||'اولین ستاره'}</p><p>${p.updated_at?'آخرین ذخیره: '+new Date(p.updated_at).toLocaleString('fa-IR'):'هنوز ذخیره نشده'}</p><div class="project-actions">${button('باز کردن','open-project','primary',`data-id="${esc(p.id)}"`)}${button('تغییر نام','rename-project','secondary',`data-id="${esc(p.id)}"`)}${button('حذف','delete-project','ghost',`data-id="${esc(p.id)}"`)}</div></article>`).join('')}</div>`:`<section class="panel empty"><h2>اولین بازی‌ات منتظر توست</h2><p>یک مرحله انتخاب کن تا پروژه‌ات ساخته شود.</p>${button('شروع اولین بازی','start','primary')}</section>`}`;}
function blockEditor(){return `<section class="panel editor-panel" id="blocks-panel" aria-labelledby="blocks-title"><div class="editor-tabs" role="tablist" aria-label="نمایش تنظیمات"><button id="blocks-tab" role="tab" aria-selected="true" aria-controls="blocks-view" data-action="view-blocks">بلوک‌ها</button><button id="code-tab" role="tab" aria-selected="false" aria-controls="code-view" data-action="view-code">نمای کد تنظیمات</button></div><div id="blocks-view" role="tabpanel" aria-labelledby="blocks-tab"><h2 id="blocks-title">تنظیمات بازی</h2><p>این بلوک‌ها ویژگی‌های بازی را تنظیم می‌کنند.</p>${Object.entries(fields).map(([key,f])=>`<div class="setting-block ${selected===key?'selected':''}" data-block="${key}"><button class="block-select" data-action="select-block" data-key="${key}" aria-pressed="${selected===key}">${f.title}</button><label for="setting-${key}">مقدار فعلی: <output data-output="${key}">${fa(draft[key])}</output> ${f.unit}</label><div class="value-control"><button class="stepper" data-action="decrease" data-key="${key}" aria-label="کاهش ${f.title}">−</button><input id="setting-${key}" data-setting="${key}" type="text" inputmode="numeric" value="${draft[key]}" aria-describedby="range-${key} error-${key}"><button class="stepper" data-action="increase" data-key="${key}" aria-label="افزایش ${f.title}">+</button></div><small id="range-${key}">از ${fa(f.min)} تا ${fa(f.max)} ${f.unit}</small><span class="field-error" id="error-${key}" aria-live="polite"></span></div>`).join('')}</div><div id="code-view" role="tabpanel" aria-labelledby="code-tab" hidden><h2>نمای کد تنظیمات</h2><p>همان مقدارهای بلوک‌ها؛ کد دلخواه در این نسخه اجرا نمی‌شود.</p><pre dir="ltr"><code id="settings-code">${codeText()}</code></pre></div><div class="editor-bottom">${button('واگرد','undo','secondary',history.length?'':'disabled')}${button('ازنو','redo','secondary',redo.length?'':'disabled')}${button('بازگردانی تنظیمات مرحله','restore','ghost')}</div></section>`;}
function codeText(){return esc(`game.settings = {\n  speed: ${draft.speed},\n  jumpHeight: ${draft.jump},\n  starScore: ${draft.starScore}\n};`);}
function workshop(){if(!active)return '<p>پروژه پیدا نشد.</p>';const l=currentLesson();return `<div class="page-heading"><div><span class="eyebrow">کارگاه / ${l.title}</span><h1>${esc(active.title)}</h1><p>هدف: ستاره را بگیر، سپس به پرچم برس.</p></div>${link('خروج از کارگاه','projects')}</div><ol class="workshop-steps"><li>یک بلوک را انتخاب کن.</li><li>مقدارش را تغییر بده.</li><li>بازی را اجرا و آزمایش کن.</li></ol><div class="workshop-toolbar" aria-label="ابزارهای کارگاه">${button('اجرای بازی ▶','run','primary','id="run-button" title="Ctrl+Enter: اجرا یا ادامه"')}${button('توقف ■','stop','secondary','id="stop-button" title="Escape: توقف"')}${button('شروع دوباره ↻','restart','secondary','title="R: شروع دوباره با فوکوس بازی"')}${button('ذخیره','save','secondary','title="Ctrl+S: ذخیره"')}${button('دانلود نسخه پروژه','export-project','ghost')}${button('راهنمایی','coach','ghost')}<label class="sound-toggle"><input type="checkbox" id="sound" ${sound?'checked':''}> صدای ستاره</label></div><p id="save-status" class="save-status" role="status" aria-live="polite">${esc(saveMessage||(user?'در انتظار ذخیره':'این پروژه فقط روی این دستگاه ذخیره می‌شود'))}</p><div class="workshop-mobile-tabs" aria-label="نمایش کارگاه">${button('بوم بازی 🎮','show-game-panel','secondary',`aria-pressed="${workshopView==='game'}"`)}${button('بلوک‌های کدنویسی 🧩','show-block-panel','secondary',`aria-pressed="${workshopView==='blocks'}"`)}</div><div class="workbench" data-workshop-view="${workshopView}"><section class="preview-column"><div class="panel preview-panel"><div class="panel-head"><h2>پیش‌نمایش بازی</h2><div class="score-pill"><span><b id="score">۰</b> امتیاز</span><span><b id="elapsed" dir="ltr">۰۰:۰۰</b> زمان</span></div></div><p class="goal">${l.title}: ستاره ✦ سپس پرچم ⚑ · ${fa(l.xp)} XP</p><div id="game-stage" class="game-stage" tabindex="0" role="region" aria-label="محیط بازی؛ حرکت با جهت‌ها، پرش با Space" aria-describedby="game-controls"><div class="stage-sun"></div><div class="cloud cloud-one"></div><span class="star-collect" aria-label="ستاره">✦</span><span class="player-sprite" aria-label="شخصیت">●</span><span class="flag-sprite" aria-label="پرچم">⚑</span><div class="stage-platform platform-one"></div>${l.id==='careful-jump'?'<div class="stage-platform platform-two"></div>':''}<div class="stage-ground"></div><span class="focus-indicator">کنترل بازی فعال است</span></div><p id="game-controls" class="controls-hint">بازی را لمس کن یا با Tab انتخاب کن؛ جهت‌ها: حرکت · Space: پرش</p><div class="touch-controls" aria-label="کنترل‌های لمسی"><button data-touch="left" aria-label="حرکت به چپ">◀ چپ</button><button data-touch="jump" aria-label="پرش">↑ پرش</button><button data-touch="right" aria-label="حرکت به راست">راست ▶</button></div></div><section class="panel console-panel"><h2>کنسول اجرا</h2><p id="run-state" role="status" aria-live="polite">آماده</p><p id="console-message">بلوک‌ها تنظیمات را تغییر می‌دهند. اجرای بازی، کنترل دستی را فعال می‌کند.</p>${button('ثبت دوباره پیشرفت','retry-progress','secondary',pendingCompletion?'':'hidden')}</section></section><div class="editor-column">${blockEditor()}<section class="panel coach-tip">${avatar()}<div><b>هوپی، مربی بازی‌سازی</b><p id="hopi-feedback" aria-live="polite">${fields[selected].hint}</p>${button('راهنمایی بیشتر','coach')}</div></section></div></div>`;}
function help(){return `<h1>راهنما و مربی هوپی</h1><section class="panel coach-tip">${avatar()}<div><h2>سلام! من هوپی هستم.</h2><p>HPLGAME یک کارگاه فارسی برای یادگیری برنامه‌نویسی با ساخت و آزمایش بازی است. یک مقدار را تغییر بده و نتیجه را ببین.</p>${button('نمایش دوباره آموزش اولیه','onboarding','primary')}</div></section><section class="panel"><h2>کنترل‌ها و میانبرها</h2><ul><li>جهت‌ها: حرکت؛ Space: پرش، فقط با فوکوس بازی.</li><li>Ctrl+Enter: اجرا؛ Ctrl+S: ذخیره؛ Ctrl+Z: واگرد؛ Ctrl+Shift+Z: ازنو.</li><li>Escape: بستن راهنما یا توقف؛ R: شروع دوباره با فوکوس بازی.</li><li>روی موبایل دکمه چپ، راست یا پرش را نگه دار.</li></ul><p>توقف، موقعیت را نگه می‌دارد. شروع دوباره، امتیاز، زمان، ستاره و موقعیت را از اول می‌کند. تنظیمات تازه از اجرای بعدی اعمال می‌شوند.</p><p>در تعارض نسخه، ذخیره متوقف می‌شود. نسخه این پنجره را دانلود کن و پروژه حساب را دوباره باز کن.</p></section>`;}
function privacy(){return `<article class="panel legal"><h1>حریم خصوصی HPLGAME</h1><p>این متن پیش‌نویس محصول است؛ پیش از عرضه حساب کودکان باید با حوزه فعالیت و روش رضایت والدین تطبیق داده شود.</p><h2>اطلاعات و دلیل جمع‌آوری</h2><p>ایمیل برای ورود و تأیید لازم است. موبایل فقط برای تکمیل پروفایل اولیه دریافت می‌شود و خصوصی می‌ماند؛ ورود با موبایل یا پیامک فعال نیست. نام کامل، تنظیمات پروژه، امتیاز، زمان و پیشرفت برای ادامه یادگیری نگه‌داری می‌شوند.</p><p>رمز فقط به سرویس Auth ارسال می‌شود؛ مدیر رمز واقعی را نمی‌بیند. رمز و کد یک‌بارمصرف در مرورگر، پروژه و CSV ذخیره نمی‌شوند. داده نشست ورود فقط در SessionStorage همان تب قرار دارد.</p><h2>کاربران کم‌سن</h2><p>حساب آنلاین فعلاً ویژه والد یا کاربر ۱۸ سال به بالاست. حساب مستقل کودکان تا تکمیل فرایند واقعی رضایت والدین فعال نمی‌شود. کاربر احراز‌هویت‌نشده محتوای عمومی را می‌بیند اما به کارگاه، پروژه و پیشرفت دسترسی ندارد.</p><h2>دسترسی و حذف</h2><p>هر کاربر فقط داده‌های خودش را می‌بیند. مدیر تأییدشده برای پشتیبانی به اطلاعات تماس و پیشرفت دسترسی دارد؛ این اطلاعات عمومی نیستند.</p><p>از داشبورد «درخواست حذف حساب و داده‌ها» را بزن. درخواست خصوصی ثبت می‌شود؛ مدیر پس از احراز مالکیت، حذف را در سرویس انجام می‌دهد. ثبت درخواست به معنی حذف فوری نیست.</p><p>نشست این تب با بستن تب پایان می‌یابد. داده حساب در Supabase نگه‌داری می‌شود. سیاست نگه‌داری، حوزه قانونی و راه تماس مسئول پشتیبانی باید پیش از عرضه حساب کودکان تعیین شوند.</p>${user?button('درخواست حذف داده‌ها','deletion-request'):link('ورود','login')}</article>`;}
function terms(){return `<article class="panel legal"><h1>قوانین استفاده</h1><p>دو مرحله فعلی رایگان‌اند. دنیای سوم نمونه توسعه است. اشتراک، پرداخت و انتشار عمومی فعال نیست.</p><p>اطلاعات تماس دیگران یا محتوای آسیب‌زا در عنوان پروژه ننویس. رمز حساب را در اختیار دیگران قرار نده. داده مهمان با پاک کردن مرورگر از بین می‌رود.</p><p>حساب آنلاین فقط برای بزرگسال یا والد است. فرایند واقعی رضایت والدین باید پیش از ارائه حساب مستقل کودکان تکمیل شود.</p><p>XP آموزشی است و ارزش مالی، جایزه یا گواهی معتبر ندارد. در قطع اینترنت، پیام ذخیره را بررسی کن.</p>${link('حریم خصوصی','privacy')}</article>`;}
function authField(name,label,type='text',extra=''){return `<div class="form-field"><label for="auth-${name}">${label}</label><div class="input-row"><input id="auth-${name}" name="${name}" type="${type}" ${extra}>${type==='password'?`<button type="button" class="password-eye stepper" data-action="toggle-password" data-target="auth-${name}" aria-label="نمایش رمز" aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="12" cy="12" r="2.5" fill="none" stroke="currentColor" stroke-width="2"/><path class="eye-slash" d="M3 3l18 18" stroke="currentColor" stroke-width="2"/></svg></button>`:''}</div><span class="field-error" id="auth-error-${name}" aria-live="polite"></span></div>`;}
function authPage(mode){
  if(!['login','signup','otp','forgot','reset'].includes(mode))return `<h1>صفحه پیدا نشد</h1>${link('بازگشت به خانه','')}`;
  if(mode==='forgot'||mode==='reset')return `<section class="panel auth-panel"><h1>ورود بدون رمز</h1><p>برای ورود کافی است کد یک‌بارمصرف ایمیل بگیری؛ رمز قبلی لازم نیست.</p>${link('دریافت کد ورود','login','primary')}</section>`;
  if(mode==='otp')return `<section class="panel auth-panel"><h1>کد تأیید را وارد کن</h1><p>کد ارسال‌شده به <strong dir="ltr">${esc(otpState.email)}</strong> را وارد کن.</p><form id="auth-form" data-mode="otp" novalidate>${authField('otp','کد تأیید','text','inputmode="numeric" autocomplete="one-time-code" dir="ltr" maxlength="8" minlength="6" required')}<p id="auth-message" role="status" aria-live="polite"></p><button type="submit" class="btn primary" ${!configured?'disabled':''}>تأیید کد و ادامه</button></form><p id="otp-countdown" class="otp-countdown" role="status"></p><div class="auth-links">${button('ارسال دوباره کد','resend-otp','secondary','disabled')}${link('تغییر ایمیل','login','ghost')}${button('انصراف','cancel-auth','ghost')}</div><p class="auth-security">کد تأیید و رمز عبور در مرورگر ذخیره نمی‌شوند.</p></section>`;
  const signup=mode==='signup';
  return `<section class="panel auth-panel"><h1>${signup?'ثبت‌نام و شروع یادگیری':'ورود به HPLGAME'}</h1>${pendingIntent?'<p class="auth-wall-note">برای ادامه، وارد حساب شو یا ثبت‌نام کن.</p>':''}${!configured?'<p class="notice">حساب آنلاین هنوز فعال نشده است. راهنمای اتصال Supabase داخل بسته قرار دارد؛ تا زمان تنظیم، مسیر و کارگاه قفل می‌مانند.</p>':''}<p>${signup?'اطلاعات اولیه را ثبت کن؛ سپس ایمیل را با کد تأیید کن.':'ایمیل حساب خودت را وارد کن تا کد ورود دریافت کنی.'}</p><form id="auth-form" data-mode="${mode}" novalidate>${signup?`${authField('fullName','نام کامل','text','autocomplete="name" maxlength="80" required')}${authField('phone','شماره موبایل ایران','tel','autocomplete="tel" inputmode="numeric" dir="ltr" maxlength="11" required')}`:''}${authField('email','ایمیل','email','autocomplete="email" inputmode="email" dir="ltr" required maxlength="254"')}${signup?`${authField('password','رمز عبور','password','autocomplete="new-password" required minlength="12" maxlength="128"')}${authField('confirm','تکرار رمز عبور','password','autocomplete="new-password" required maxlength="128"')}<p id="password-strength" aria-live="polite">رمز پیشنهادی: دست‌کم ۱۲ نویسه.</p><label for="account-kind">نوع حساب</label><select id="account-kind" name="accountKind" required><option value="">انتخاب کن</option><option value="adult">۱۸ سال یا بالاتر</option><option value="guardian">والد یا سرپرست بزرگسال</option></select><span class="field-error" id="auth-error-accountKind" aria-live="polite"></span><label class="check-label"><input type="checkbox" name="terms"><span><a href="#/terms">قوانین</a> و <a href="#/privacy">حریم خصوصی</a> را می‌پذیرم.</span></label><span class="field-error" id="auth-error-terms" aria-live="polite"></span>`:''}<p id="auth-message" role="status" aria-live="polite"></p><button type="submit" class="btn primary" ${!configured?'disabled':''}>${signup?'ثبت‌نام و ارسال کد تأیید':'ارسال کد ورود'}</button></form><div class="auth-links">${signup?link('رفتن به ورود','login','ghost'):link('ساخت حساب','signup','ghost')}${button('انصراف','cancel-auth','ghost')}</div><p class="auth-security">کد ورود و رمز عبور را با کسی به اشتراک نگذار.</p></section>`;
}
function admin(){if(!user||profile?.role!=='admin')return '<h1>دسترسی مجاز نیست</h1><p>پنل مدیری فقط برای مدیر تأییدشده در دیتابیس تازه است.</p>';return `<h1>مدیریت HPLGAME</h1><p>دسترسی در دیتابیس بررسی می‌شود؛ هیچ رمزی در این پنل نیست.</p><form id="admin-form" class="admin-search"><label for="admin-search">جست‌وجوی نام، ایمیل یا موبایل</label><input id="admin-search" name="search" type="search" maxlength="80"><label for="admin-role">نقش</label><select id="admin-role" name="role"><option value="">همه</option><option value="student">دانش‌آموز</option><option value="admin">مدیر</option></select><button class="btn primary">جست‌وجو</button></form><p id="admin-status" role="status">در حال دریافت…</p><div class="table-wrap"><table><caption>کاربران مجاز</caption><thead><tr><th>نام و نام‌خانوادگی</th><th>ایمیل تأییدشده</th><th>موبایل</th><th>عضویت</th><th>نقش</th><th>آخرین فعالیت آموزشی</th><th>پیشرفت</th></tr></thead><tbody id="admin-rows"></tbody></table></div><div class="admin-actions">${button('صفحه قبل','admin-prev')}${button('صفحه بعد','admin-next')}${button('خروجی CSV صفحه فعلی','admin-csv')}</div><section class="panel"><h2>درخواست‌های حذف داده</h2><div id="deletion-requests">در حال دریافت…</div><p>حذف نهایی پس از احراز مالکیت، در پنل امن Supabase انجام شود.</p></section>`;}
function toast(text){const e=document.querySelector('#toast');if(e)e.textContent=text;}
function navigate(path){if(location.hash==='#/'+path){route=path;render();}else location.hash='#/'+path;}
function stopAnimation(){cancelAnimationFrame(frame);lastFrame=0;}
function resetInput(){Object.keys(input).forEach(k=>input[k]=false);}
function pauseGame(){if(game?.status==='running')game.stop();stopAnimation();resetInput();paintGame();}
function openProject(id){if(!user)return openAuthWall({kind:'project',id,route:'#/projects'});const p=projects.find(p=>p.id===id);if(!p)return;active=safeProject(p);draft={...active.project_data.settings};history=[];redo=[];dirty=false;revision=0;saveMessage=p.updated_at?`${user?'در حساب شما':'روی این دستگاه'} ذخیره شد · ${new Date(p.updated_at).toLocaleTimeString('fa-IR')}`:'';game=new Game(draft,currentLesson().id);navigate('workshop/'+id);}
async function startLesson(id){
  if(!user)return openAuthWall({kind:'lesson',id,route:'#/learn'});
  const l=lessons.find(l=>l.id===id);if(!l||lessonStatus(l,progress)==='locked'){toast('اول پیش‌نیاز مرحله را کامل کن.');return;}
  if(pendingCompletion&&!await saveCompletion())return;
  let p=projects.find(p=>p.project_data.lesson_id===id);
  if(!p){p=newProject(l);projects.unshift(p);active=p;draft={...p.project_data.settings};dirty=true;revision++;if(!await flushSave()){navigate('workshop/'+p.id);return;}}
  if(progress[id]?.status!=='completed'){
    if(user){try{await recordProgress(id,'in_progress');}catch(e){toast(friendlyError(e));}}
    progress[id]={...progress[id],status:'in_progress'};if(!user)writeGuest();
  }
  openProject(p.id);if(!onboarding)setTimeout(()=>showOnboarding(0),0);
}
function updateSetting(key,raw,control){const result=validateValue(key,raw),error=document.querySelector('#error-'+key);if(error)error.textContent=result.error||'';control?.setAttribute('aria-invalid',result.error?'true':'false');if(result.error)return false;if(result.value===draft[key])return true;history.push({...draft});if(history.length>50)history.shift();redo=[];draft[key]=result.value;selected=key;revision++;dirty=true;syncEditor();queueSave();return true;}
function syncEditor(){for(const key of Object.keys(fields)){const out=document.querySelector(`[data-output="${key}"]`);if(out)out.textContent=fa(draft[key]);const block=document.querySelector(`[data-block="${key}"]`);block?.classList.toggle('selected',selected===key);block?.querySelector('button')?.setAttribute('aria-pressed',String(selected===key));}document.querySelector('#settings-code')?.replaceChildren(document.createTextNode(`game.settings = {\n  speed: ${draft.speed},\n  jumpHeight: ${draft.jump},\n  starScore: ${draft.starScore}\n};`));for(const a of ['undo','redo']){const el=document.querySelector(`[data-action="${a}"]`);if(el)el.disabled=!(a==='undo'?history:redo).length;}}
function setSaveMessage(text){saveMessage=text;const e=document.querySelector('#save-status');if(e)e.textContent=text;}
function queueSave(){clearTimeout(saveTimer);setSaveMessage('تغییرات ذخیره‌نشده؛ در انتظار ذخیره…');saveTimer=setTimeout(()=>flushSave(),700);}
async function flushSave(){
  clearTimeout(saveTimer);if(savePromise){await savePromise;if(!dirty)return true;}if(!active||!dirty)return true;
  const snapshot={...active,project_data:{lesson_id:currentLesson().id,settings:{...draft}}},sentRevision=revision,owner=user?.id;
  setSaveMessage('در حال ذخیره…');
  savePromise=(async()=>{try{let saved;if(owner){if(!online)throw new Error('offline');saved=await saveProject(snapshot,owner);}else{saved={...snapshot,updated_at:new Date().toISOString()};projects=projects.map(p=>p.id===saved.id?saved:p);if(!writeGuest())throw new Error('storage');}if(user?.id!==owner)return false;active={...saved};projects=projects.map(p=>p.id===saved.id?saved:p);dirty=revision!==sentRevision;setSaveMessage(dirty?'تغییرات تازه در انتظار ذخیره…':`${owner?'در حساب شما ذخیره شد':'این پروژه فقط روی این دستگاه ذخیره شد'} · ${new Date(saved.updated_at).toLocaleTimeString('fa-IR')}`);return true;}catch(e){setSaveMessage(e.message==='storage'?'ذخیره نشد؛ فضای مرورگر در دسترس نیست. نسخه پروژه را دانلود کن.':`ذخیره نشد؛ تلاش دوباره. ${friendlyError(e)}`);return false;}finally{savePromise=null;}})();
  const result=await savePromise;if(result&&dirty)queueSave();return result;
}
function paintGame(){if(!game)return;const stage=document.querySelector('#game-stage');if(!stage)return;const player=stage.querySelector('.player-sprite');player.style.left=(game.x/WORLD.width*100)+'%';player.style.top=((game.y-WORLD.playerSize)/WORLD.height*100)+'%';stage.querySelector('.star-collect').hidden=game.collected;stage.classList.toggle('collected',game.collected);document.querySelector('#score').textContent=fa(game.score);document.querySelector('#elapsed').textContent=formatTime(game.elapsed);const labels={ready:'آماده',running:'در حال اجرا',paused:'متوقف',success:'موفق',error:'خطا'},out=document.querySelector('#run-state');if(out.textContent!==labels[game.status])out.textContent=labels[game.status];const run=document.querySelector('#run-button');run.disabled=game.status==='running';run.textContent=game.status==='paused'?'ادامه بازی ▶':'اجرای بازی ▶';document.querySelector('#stop-button').disabled=game.status!=='running';}
function animate(){stopAnimation();frame=requestAnimationFrame(loop);}
function loop(now){if(!game||game.status!=='running')return;const hadStar=game.collected;game.tick(lastFrame?(now-lastFrame)/1000:0,input);lastFrame=now;paintGame();if(!hadStar&&game.collected){document.querySelector('#console-message').textContent='ستاره را گرفتی! حالا به پرچم سمت راست برس.';if(sound)playSound();}if(game.status==='success'){resetInput();completeLesson();return;}if(game.status==='error'){resetInput();showModal('دوباره تلاش کنیم','<p>زمان تمرین تمام شد. ارتفاع ۴ یا بیشتر را امتحان کن؛ اول ستاره و سپس پرچم.</p>'+button('تلاش دوباره','restart','primary'));return;}frame=requestAnimationFrame(loop);}
function playSound(){try{audioContext||=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.frequency.value=880;gain.gain.value=.08;gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.14);oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.start();oscillator.stop(audioContext.currentTime+.15);}catch{}}
function run(){if([...document.querySelectorAll('[data-setting]')].some(e=>e.getAttribute('aria-invalid')==='true')){toast('اول مقدار نامعتبر را اصلاح کن.');return;}if(game.status!=='paused')game=new Game(draft,currentLesson().id);game.start();document.querySelector('#game-stage')?.focus();document.querySelector('#console-message').textContent='جهت‌ها: حرکت · Space: پرش. تنظیمات تا اجرای بعدی ثابت‌اند.';paintGame();animate();}
async function saveCompletion(){if(!pendingCompletion)return true;const c=pendingCompletion;try{if(user)await recordProgress(c.lesson,'completed',c.score,c.time);else if(!writeGuest())throw new Error('storage');pendingCompletion=null;document.querySelector('[data-action="retry-progress"]')?.setAttribute('hidden','');toast(user?'پیشرفت در حساب شما ذخیره شد.':'پیشرفت فقط روی این دستگاه ذخیره شد.');return true;}catch{toast('پیشرفت ذخیره نشد؛ «ثبت دوباره پیشرفت» را بزن.');document.querySelector('[data-action="retry-progress"]')?.removeAttribute('hidden');return false;}}
function completeLesson(){const l=currentLesson(),old=progress[l.id],earned=old?.status==='completed'?0:l.xp;progress[l.id]={...old,status:'completed',score:Math.max(old?.score||0,game.score),best_time:Math.min(old?.best_time??Infinity,game.elapsed),xp:l.xp,completed_at:new Date().toISOString()};pendingCompletion={lesson:l.id,score:game.score,time:game.elapsed};saveCompletion();const next=lessons.find(x=>x.published&&x.prerequisite===l.id);showModal(`آفرین ${esc(currentDisplayName())}!`,`<p>${fa(game.score)} امتیاز · ${formatTime(game.elapsed)} زمان · ${fa(earned)} XP تازه</p><p>XP هر مرحله فقط یک‌بار به مجموع اضافه می‌شود.</p><div class="modal-actions">${next?button('رفتن به مرحله بعدی ➔','lesson','primary',`data-lesson="${next.id}"`):'<p>همه مراحل فعلی را تمام کردی!</p>'}${button('تکرار مرحله','restart')}${button('بازگشت به نقشه','map')}</div>`);}

function showModal(title,html){pauseGame();if(!document.querySelector('#modal-root')?.children.length)modalReturn=document.activeElement;const root=document.querySelector('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" data-action="close-modal" aria-label="بستن پنجره">×</button><h2 id="modal-title">${title}</h2>${html}</section></div>`;document.querySelector('.app-shell').inert=true;document.querySelector('.hopi-launch').inert=true;bindActions(root);root.querySelector('button,input,select')?.focus();root.onkeydown=e=>{if(e.key==='Escape'){e.stopPropagation();closeModal();}if(e.key==='Tab'){const all=[...root.querySelectorAll('button:not([disabled]),input,select,a[href]')].filter(el=>!el.hidden),first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};}
function closeModal(){document.querySelector('#modal-root')?.replaceChildren();document.querySelector('.app-shell').inert=false;document.querySelector('.mobile-nav').inert=false;document.querySelector('.hopi-launch').inert=false;document.querySelectorAll('.hopi-highlight').forEach(e=>e.classList.remove('hopi-highlight'));modalReturn?.focus();}
function showCoach(more=false){showModal('هوپی، مربی بازی‌سازی',`<div class="coach-tip">${avatar()}<p>خوش اومدی ${esc(currentDisplayName())}! 🚀 من هوپی هستم، مربی بازی‌سازی تو.</p></div><p>${fields[selected].hint}</p>${more?'<ol><li>پرش را روی ۴ بگذار.</li><li>اجرای بازی را بزن.</li><li>نزدیک ستاره، Space یا پرش را بزن.</li><li>ستاره را بگیر و به پرچم برو.</li></ol>':''}<div class="modal-actions">${button('راهنمایی بیشتر','coach-more')}${button('فهمیدم','close-modal','primary')}</div>`);document.querySelector(`[data-block="${selected}"]`)?.classList.add('hopi-highlight');}
const onboardingSteps=[['به HPLGAME خوش آمدی!','اینجا قدم‌به‌قدم بازی‌سازی یاد می‌گیری.'],['با ساختن یاد بگیر','تنظیمات را عوض کن و اثرشان را ببین.'],['محیط بازی تو','هدف: ستاره، سپس پرچم.'],['بلوک‌های برنامه‌نویسی','بلوک‌ها سرعت، پرش و امتیاز را تنظیم می‌کنند.'],['اجرا و شروع دوباره','اجرا کنترل دستی را فعال می‌کند؛ شروع دوباره همه‌چیز را از اول می‌کند.'],['مربی هوپی','سلام! من هوپی هستم، مربی بازی‌سازی تو. از دکمه راهنمایی هوپی کمک بگیر.']];
function showOnboarding(step){const [title,text]=onboardingSteps[step];showModal(title,`<p>قدم ${fa(step+1)} از ۶</p><p>${text}</p><div class="modal-actions">${button('رد کردن آموزش','finish-onboarding')}${step?button('قبلی','onboarding-step','secondary',`data-step="${step-1}"`):''}${button(step===5?'شروع کنیم':'بعدی',step===5?'finish-onboarding':'onboarding-step','primary',`data-step="${step+1}"`)}</div>`);document.querySelector(step===3?'#blocks-panel':step===4?'#run-button':'#game-stage')?.classList.add('hopi-highlight');}
async function finishOnboarding(){try{if(user){const db=await getClient();const {error}=await db.from('profiles').update({onboarding_completed:true}).eq('id',user.id);if(error)throw error;}onboarding=true;if(!user&&!writeGuest())throw new Error('storage');closeModal();}catch{toast('وضعیت آموزش ذخیره نشد؛ دوباره تلاش کن.');}}
function download(name,body,type='application/json'){const blob=new Blob([body],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function restart(){closeModal();game=new Game(draft,currentLesson().id);paintGame();run();}

function bindActions(root=document){root.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',()=>handleAction(el.dataset.action,el)));}
function bind(){
  bindDiscovery({navigate,render,toast,onSubmitIdea:text=>submitPrototypeIdea(text,{navigate,render,toast})});
  bindPrototype({navigate,render,toast});
  bindActions();document.querySelector('.skip')?.addEventListener('click',e=>{e.preventDefault();document.querySelector('#main-content').focus();});
  document.querySelectorAll('[data-setting]').forEach(el=>el.addEventListener('input',()=>updateSetting(el.dataset.setting,el.value,el)));
  document.querySelector('#sound')?.addEventListener('change',e=>sound=e.target.checked);
  document.querySelector('#auth-form')?.addEventListener('submit',submitAuth);
  document.querySelectorAll('#auth-form input,#auth-form select').forEach(el=>el.addEventListener('input',()=>validateAuthForm(document.querySelector('#auth-form'),false)));
  document.querySelector('#auth-password')?.addEventListener('input',e=>{const out=document.querySelector('#password-strength');if(out)out.textContent='قدرت رمز: '+['ضعیف','ضعیف','متوسط','خوب','قوی'][passwordStrength(e.target.value)];});
  document.querySelector('#profile-form')?.addEventListener('submit',submitProfile);
  document.querySelector('#admin-form')?.addEventListener('submit',e=>{e.preventDefault();adminOffset=0;loadAdmin();});if(route==='admin'&&profile?.role==='admin')loadAdmin();
  const stage=document.querySelector('#game-stage');
  stage?.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'||e.code==='Space'){e.preventDefault();input[e.code==='Space'?'jump':e.key==='ArrowLeft'?'left':'right']=true;}if(e.key.toLowerCase()==='r'&&!e.ctrlKey&&!e.metaKey){e.preventDefault();restart();}});
  stage?.addEventListener('keyup',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'||e.code==='Space'){e.preventDefault();input[e.code==='Space'?'jump':e.key==='ArrowLeft'?'left':'right']=false;}});
  stage?.addEventListener('blur',resetInput);
  document.querySelectorAll('[data-touch]').forEach(el=>{el.addEventListener('pointerdown',e=>{e.preventDefault();el.setPointerCapture(e.pointerId);input[el.dataset.touch]=true;});for(const event of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(event,()=>input[el.dataset.touch]=false);el.addEventListener('keydown',e=>{if(e.code==='Space'||e.key==='Enter'){e.preventDefault();input[el.dataset.touch]=true;}});el.addEventListener('keyup',()=>input[el.dataset.touch]=false);el.addEventListener('blur',()=>input[el.dataset.touch]=false);});
  document.querySelectorAll('[role="tab"]').forEach(el=>el.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const code=e.key==='End'||e.key.startsWith('Arrow')&&el.id==='blocks-tab';handleAction(code?'view-code':'view-blocks');document.querySelector(code?'#code-tab':'#blocks-tab').focus();}}));
}
async function handleAction(action,el){
  if(action==='start'){if(!configured)return navigate('studio/coach');if(!user)return openAuthWall({kind:'lesson',id:nextLesson().id,route:'#/learn'});return startLesson(nextLesson().id);}
  if(action==='lesson'){if(!user)return openAuthWall({kind:'lesson',id:el.dataset.lesson,route:'#/learn'});closeModal();return startLesson(el.dataset.lesson);}
  if(action==='open-project'){if(!user)return openAuthWall({route:'#/projects'});return openProject(el.dataset.id);}
  if(action==='new-project'){if(!user)return openAuthWall({route:'#/projects'});const p=newProject(nextLesson());projects.unshift(p);openProject(p.id);dirty=true;revision++;queueSave();return;}
  if(action==='run')return run();if(action==='stop')return pauseGame();if(action==='restart')return restart();
  if(action==='save')return flushSave();if(action==='retry-progress')return saveCompletion();
  if(action==='discard')return showModal('خروج بدون ذخیره؟','<p>تغییرات این پنجره از دست می‌روند. ابتدا نسخه پروژه را دانلود کن.</p>'+button('دانلود نسخه پروژه','export-project')+button('خروج بدون ذخیره','confirm-discard','primary')+button('لغو','close-modal'));
  if(action==='confirm-discard'){clearTimeout(saveTimer);dirty=false;closeModal();location.hash=blockedDestination;return;}
  if(action==='map'){closeModal();navigate('learn');return;}
  if(action==='export-project')return download('hplgame-project.json',JSON.stringify({title:active.title,project_data:{lesson_id:currentLesson().id,settings:draft}},null,2));
  if(action==='select-block'){selected=el.dataset.key;syncEditor();document.querySelector('#setting-'+selected)?.focus();return;}
  if(action==='increase'||action==='decrease'){const key=el.dataset.key,n=draft[key]+(action==='increase'?1:-1),field=document.querySelector('#setting-'+key);if(updateSetting(key,n,field))field.value=n;return;}
  if(action==='undo'||action==='redo'){const from=action==='undo'?history:redo,to=action==='undo'?redo:history;if(!from.length)return;to.push({...draft});draft=from.pop();revision++;dirty=true;for(const key of Object.keys(fields)){const el=document.querySelector('#setting-'+key);el.value=draft[key];el.setAttribute('aria-invalid','false');document.querySelector('#error-'+key).textContent='';}syncEditor();queueSave();return;}
  if(action==='view-code'||action==='view-blocks'){const code=action==='view-code';document.querySelector('#code-view').hidden=!code;document.querySelector('#blocks-view').hidden=code;document.querySelector('#code-tab').setAttribute('aria-selected',String(code));document.querySelector('#blocks-tab').setAttribute('aria-selected',String(!code));return;}
  if(action==='restore')return showModal('تنظیمات مرحله بازگردانده شود؟','<p>سرعت، پرش و امتیاز به حالت اولیه برمی‌گردد.</p>'+button('بازگردانی','confirm-restore','primary')+button('لغو','close-modal'));
  if(action==='confirm-restore'){history.push({...draft});redo=[];draft={...currentLesson().defaults};dirty=true;revision++;closeModal();render();queueSave();return;}
  if(action==='close-modal')return closeModal();if(action==='coach'){if(!configured)return navigate('studio/coach');if(!user)return openAuthWall({route:'#/help'});return showCoach();}if(action==='coach-more')return showCoach(true);
  if(action==='onboarding')return showOnboarding(0);if(action==='onboarding-step')return showOnboarding(Number(el.dataset.step));if(action==='finish-onboarding')return finishOnboarding();
  if(action==='toggle-password'){const target=document.getElementById(el.dataset.target),show=target.type==='password';target.type=show?'text':'password';el.setAttribute('aria-pressed',String(show));el.setAttribute('aria-label',(show?'مخفی کردن':'نمایش')+' رمز');return;}
  if(action==='show-game-panel'||action==='show-block-panel'){workshopView=action==='show-game-panel'?'game':'blocks';document.querySelector('.workbench').dataset.workshopView=workshopView;document.querySelector('[data-action="show-game-panel"]').setAttribute('aria-pressed',String(workshopView==='game'));document.querySelector('[data-action="show-block-panel"]').setAttribute('aria-pressed',String(workshopView==='blocks'));return;}
  if(action==='resend-otp')return resendOtp();
  if(action==='cancel-auth'){clearOtpState();pendingIntent=null;authReturnHash='#/dashboard';navigate('');return;}
  if(action==='logout'){if(!await flushSave()||pendingCompletion&&!await saveCompletion()){toast('داده ذخیره نشده؛ ابتدا ذخیره یا دانلود کن.');return;}const db=await getClient();const {error}=await db.auth.signOut();if(error)toast(friendlyError(error));else{clearAccount();navigate('');}return;}
  if(action==='reload-account')return refreshAccount();
  if(action==='rename-project'){
    const p=projects.find(p=>p.id===el.dataset.id);showModal('تغییر نام پروژه',`<form id="rename-form"><label for="project-title">نام پروژه</label><input id="project-title" required maxlength="80" value="${esc(p.title)}"><p id="rename-error" role="alert"></p><button class="btn primary">ذخیره نام</button></form>`);
    document.querySelector('#rename-form').addEventListener('submit',async e=>{e.preventDefault();const title=document.querySelector('#project-title').value.trim();if(!title)return;const btn=e.target.querySelector('button');btn.disabled=true;try{let saved={...p,title,updated_at:new Date().toISOString()};if(user)saved=await saveProject({...p,title},user.id);const previous=projects;projects=projects.map(x=>x.id===p.id?saved:x);if(!user&&!writeGuest()){projects=previous;throw new Error('storage');}closeModal();render();}catch(error){document.querySelector('#rename-error').textContent=friendlyError(error);btn.disabled=false;}});return;
  }
  if(action==='delete-project'){const p=projects.find(p=>p.id===el.dataset.id);return showModal('حذف پروژه؟',`<p>«${esc(p.title)}» حذف می‌شود و قابل بازگشت نیست. پیش از حذف می‌توانی پروژه را دانلود کنی.</p>`+button('حذف این پروژه','confirm-delete','primary',`data-id="${esc(p.id)}"`)+button('لغو','close-modal'));}
  if(action==='confirm-delete'){el.disabled=true;try{if(user){const db=await getClient();const {error}=await db.from('projects').delete().eq('id',el.dataset.id).eq('user_id',user.id);if(error)throw error;}const previous=projects;projects=projects.filter(p=>p.id!==el.dataset.id);if(!user&&!writeGuest()){projects=previous;throw new Error('storage');}closeModal();render();}catch(error){el.disabled=false;toast(friendlyError(error));}return;}
  if(action==='deletion-request'){if(!user){toast('برای درخواست حذف حساب وارد شو.');return;}return showModal('درخواست حذف حساب و داده‌ها','<p>درخواست خصوصی ثبت می‌شود. مدیر پس از احراز مالکیت، حساب و داده‌ها را حذف می‌کند.</p>'+button('ثبت درخواست حذف','confirm-deletion','primary')+button('لغو','close-modal'));}
  if(action==='confirm-deletion'){el.disabled=true;try{const db=await getClient();const {error}=await db.from('deletion_requests').upsert({user_id:user.id},{onConflict:'user_id'});if(error)throw error;closeModal();toast('درخواست ثبت شد؛ حذف فوری انجام نشده است.');}catch(error){el.disabled=false;toast(friendlyError(error));}return;}
  if(action==='import-guest'){el.disabled=true;try{const guest=JSON.parse(localStorage.getItem(GUEST_KEY)||'{}');for(const p of (guest.projects||[]).slice(0,20)){const clean=safeProject(p);if(!projects.some(x=>x.id===clean.id))projects.push(await saveProject({...clean,version:undefined},user.id));}render();toast('پروژه‌ها وارد شدند؛ پیشرفت مهمان به حساب منتقل نمی‌شود.');}catch(error){el.disabled=false;toast(friendlyError(error));}return;}
  if(action==='admin-next'){adminOffset+=50;return loadAdmin();}if(action==='admin-prev'){adminOffset=Math.max(0,adminOffset-50);return loadAdmin();}
  if(action==='admin-csv'){const rows=[['نام','ایمیل','موبایل','ثبت‌نام','آخرین فعالیت','پیشرفت'],...adminRows.map(r=>[r.display_name,r.email,r.phone,r.created_at,r.last_activity,r.progress_percent])];return download('hplgame-users.csv','\ufeff'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
}
function validateAuthForm(form,all=true){
  const mode=form.dataset.mode,values=Object.fromEntries(new FormData(form));values.terms=!!values.terms;let errors={},valid;
  if(mode==='signup'){
    values.fullName=String(values.fullName||'').trim();valid=validateSignup(values);errors={...valid.errors};
    if(values.fullName.length<2||values.fullName.length>80)errors.fullName='نام کامل را بین ۲ تا ۸۰ نویسه وارد کن.';
    if(!/^09\d{9}$/.test(english(values.phone||'').trim()))errors.phone='موبایل باید ۱۱ رقم باشد و با ۰۹ شروع شود.';
  }
  if(mode==='login'){values.email=english(values.email||'').trim().toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(values.email)||values.email.length>254)errors.email='یک ایمیل معتبر وارد کن.';}
  if(mode==='otp'){values.otp=english(values.otp||'').trim();if(!/^\d{6,8}$/.test(values.otp))errors.otp='کد ۶ تا ۸ رقمی را وارد کن.';}
  for(const el of form.querySelectorAll('input,select')){const error=errors[el.name],out=document.querySelector('#auth-error-'+el.name);if(!out)continue;if(all||el.value||el.getAttribute('aria-invalid')==='true'){out.textContent=error||'';el.setAttribute('aria-invalid',String(!!error));}}
  return {values,errors,valid};
}
async function resendOtp(){
  if(!configured||!otpState.email||otpState.cooldown>0||authBusy)return;
  const button=document.querySelector('[data-action="resend-otp"]');authBusy=true;if(button)button.disabled=true;
  try{const db=await getClient();const result=otpState.type==='signup'?await db.auth.resend({type:'signup',email:otpState.email}):await db.auth.signInWithOtp({email:otpState.email,options:{shouldCreateUser:false,emailRedirectTo:redirectURL()}});if(result.error)throw result.error;startOtpCooldown();toast('کد تازه ارسال شد.');}
  catch(error){if(button)button.disabled=false;toast(friendlyError(error));}finally{authBusy=false;}
}
async function submitAuth(event){
  event.preventDefault();const form=event.target,mode=form.dataset.mode,submit=form.querySelector('[type="submit"]'),message=document.querySelector('#auth-message');if(authBusy||form.dataset.busy==='true'||!configured)return;
  message.textContent='';const {values,errors,valid}=validateAuthForm(form);
  if(Object.keys(errors).length){form.querySelector('[aria-invalid="true"]')?.focus();return;}
  authBusy=true;form.dataset.busy='true';submit.disabled=true;message.textContent='در حال انجام…';
  try{const db=await getClient();let result;
    if(mode==='signup'){
      result=await db.auth.signUp({email:valid.email,password:values.password,options:{emailRedirectTo:redirectURL(),data:{phone:valid.phone,full_name:values.fullName,display_name:values.fullName.slice(0,40),account_kind:values.accountKind,terms_version:'2026-10-15'}}});
      if(result.error)throw result.error;
      if(result.data?.session){await db.auth.signOut();throw new Error('email_confirmation_required');}
      if(result.data?.user?.identities?.length===0)throw new Error('already registered');
      clearOtpState();otpState.email=valid.email;otpState.type='signup';form.reset();startOtpCooldown();navigate('otp');return;
    }
    if(mode==='login'){
      result=await db.auth.signInWithOtp({email:values.email,options:{shouldCreateUser:false,emailRedirectTo:redirectURL()}});if(result.error)throw result.error;
      clearOtpState();otpState.email=values.email;otpState.type='email';form.reset();startOtpCooldown();navigate('otp');return;
    }
    if(mode==='otp'){
      if(!otpState.email)throw new Error('otp_expired');
      result=await db.auth.verifyOtp({email:otpState.email,token:values.otp,type:otpState.type});if(result.error)throw result.error;
      form.reset();await refreshAccount();if(!user||dataError)throw new Error('profile_unavailable');clearOtpState();await resumeAuthIntent();return;
    }
  }catch(error){message.textContent=friendlyError(error);}finally{authBusy=false;form.dataset.busy='false';submit.disabled=false;}
}
async function submitProfile(event){event.preventDefault();const form=event.target,name=form.displayName.value.trim();if(!name||name.length>40)return;const btn=form.querySelector('button');btn.disabled=true;try{const db=await getClient();const {error}=await db.from('profiles').update({display_name:name}).eq('id',user.id);if(error)throw error;profile.display_name=name;render();toast('نام نمایشی ذخیره شد.');}catch(e){toast(friendlyError(e));btn.disabled=false;}}
let accountEpoch=0;
function clearAccount(){accountEpoch++;clearTimeout(saveTimer);user=null;profile=null;projects=[];progress={};onboarding=false;active=null;dirty=false;pendingCompletion=null;saveMessage='';dataError='';}
async function refreshAccount(){const epoch=++accountEpoch;pauseGame();loading=true;dataError='';render();try{const data=await getAccountData();if(epoch!==accountEpoch)return;if(data){user=data.user;profile=data.profile;projects=data.projects.map(safeProject);progress=data.progress;onboarding=profile.onboarding_completed;active=null;dirty=false;}else clearAccount();}catch(error){if(epoch===accountEpoch)dataError=friendlyError(error);}finally{if(epoch===accountEpoch||!user){loading=false;render();}}}
let adminOffset=0,adminRows=[];
async function loadAdmin(){if(profile?.role!=='admin')return;const out=document.querySelector('#admin-status');try{const form=document.querySelector('#admin-form'),db=await getClient();const {data,error}=await db.rpc('admin_users',{p_search:form.elements.namedItem('search').value,p_role:form.elements.namedItem('role').value||null,p_limit:50,p_offset:adminOffset});if(error)throw error;adminRows=data.rows;out.textContent=`${fa(data.total)} کاربر · صفحه ${fa(adminOffset/50+1)} · ${fa(data.rows.length)} نتیجه`;document.querySelector('#admin-rows').innerHTML=adminRows.map(r=>`<tr><td>${esc(r.full_name||r.display_name)}</td><td dir="ltr">${esc(r.email)}<small>${r.email_confirmed_at?" · تأییدشده":" · تأیید نشده"}</small></td><td dir="ltr">${esc(r.phone||'—')}</td><td>${new Date(r.created_at).toLocaleString('fa-IR')}</td><td>${r.role==='admin'?'مدیر':'دانش‌آموز'}</td><td>${r.last_activity?new Date(r.last_activity).toLocaleDateString('fa-IR'):'در دسترس نیست'}</td><td>${fa(r.progress_percent)}٪ · ${esc(r.current_lesson||'شروع نشده')}</td></tr>`).join('')||'<tr><td colspan="7">کاربری پیدا نشد.</td></tr>';document.querySelector('[data-action="admin-next"]').disabled=adminOffset+50>=data.total;document.querySelector('[data-action="admin-prev"]').disabled=adminOffset===0;const requests=await db.from('deletion_requests').select('user_id,requested_at').order('requested_at');if(requests.error)throw requests.error;document.querySelector('#deletion-requests').innerHTML=requests.data.map(r=>`<p><code>${esc(r.user_id)}</code> · ${new Date(r.requested_at).toLocaleDateString('fa-IR')}</p>`).join('')||'<p>درخواستی ثبت نشده است.</p>';}catch(e){if(out)out.textContent=friendlyError(e);}}
let acceptedHash='',routing=false,reverting=false;
async function routeChanged(){
  if(reverting){reverting=false;return;}if(routing)return;routing=true;
  const next=location.hash.replace(/^#\/?/,'').split('?')[0]||'';
  // Static Pages uses the local prototype; configured backend routes retain their auth wall.
  const demoDestination=!configured&&({login:'studio/login',signup:'studio/signup',projects:'studio/games',dashboard:'studio/games',learn:'studio/coach',help:'studio/coach'})[next];
  if(demoDestination){routing=false;navigate(demoDestination);return;}
  if(isProtectedRoute(next)&&!user){rememberAuthIntent({route:location.hash||'#/dashboard'});route='login';acceptedHash='#/login';if(location.hash!=='#/login'){reverting=true;location.hash='#/login';}render();routing=false;return;}
  if(next==='otp'&&!otpState.email){route='login';acceptedHash='#/login';if(location.hash!=='#/login'){reverting=true;location.hash='#/login';}render();routing=false;return;}
  if(dirty&&!await flushSave()){blockedDestination=location.hash;reverting=location.hash!==acceptedHash;location.hash=acceptedHash;routing=false;showModal('تغییرات ذخیره نشده‌اند','<p>دوباره ذخیره کن یا نسخه پروژه را دانلود کن.</p>'+button('ذخیره دوباره','save','primary')+button('دانلود نسخه پروژه','export-project')+button('خروج بدون ذخیره','discard'));return;}
  if(pendingCompletion&&!await saveCompletion()){location.hash=acceptedHash;routing=false;return;}
  pauseGame();route=next;acceptedHash=location.hash;
  if(route.startsWith('workshop/')){const id=route.slice(9);if(active?.id!==id){const p=projects.find(p=>p.id===id);if(p){active=p;draft={...p.project_data.settings};game=new Game(draft,currentLesson().id);}else route='projects';}}
  render();if(!document.querySelector('[aria-modal="true"]'))document.querySelector('#main-content')?.focus({preventScroll:true});window.scrollTo(0,0);routing=false;
}
window.addEventListener('hashchange',routeChanged);
window.addEventListener('beforeunload',e=>{if(dirty||pendingCompletion){e.preventDefault();e.returnValue='';}});
window.addEventListener('online',()=>{online=true;toast('اتصال برقرار شد؛ برای همگام‌سازی، ذخیره را بزن.');});
window.addEventListener('offline',()=>{online=false;pauseGame();toast('اینترنت قطع شد؛ پروژه حساب هنوز همگام نشده است.');});
window.addEventListener('blur',pauseGame);document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseGame();});
document.addEventListener('keydown',e=>{if(document.querySelector('#modal-root')?.children.length)return;if(e.key==='Escape'){pauseGame();return;}if(!route.startsWith('workshop'))return;if(e.ctrlKey||e.metaKey){if(e.key==='Enter'){e.preventDefault();run();}if(e.key.toLowerCase()==='s'){e.preventDefault();flushSave();}if(e.key.toLowerCase()==='z'){e.preventDefault();handleAction(e.shiftKey?'redo':'undo');}}});
route=location.hash.replace(/^#\/?/,'').split('?')[0]||'';acceptedHash=location.hash;render();
if(configured){(async()=>{try{const db=await getClient();db.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT')setTimeout(()=>{clearAccount();routeChanged();},0);if(event==='SIGNED_IN'&&!authBusy&&session?.user?.id!==user?.id)setTimeout(refreshAccount,0);});const {data:{session},error}=await db.auth.getSession();if(error)throw error;if(session)await refreshAccount();await routeChanged();}catch(e){dataError=friendlyError(e);render();}})();}else routeChanged();
